import java.util.*;
interface BusUser {double getTransportFee();}
abstract class Student {String name;Student(String n){name=n;}abstract double calculateFee();double getTransportFee(){if(this instanceof BusUser)return ((BusUser)this).getTransportFee();return 0.0;}double getTotalFee(){return calculateFee()+getTransportFee();}}
class DayScholar extends Student implements BusUser {DayScholar(String n){super(n);}double calculateFee(){return 40000.0;}public double getTransportFee(){return 12000.0;}}
class Hosteller extends Student {Hosteller(String n){super(n);}double calculateFee(){return 40000.0+60000.0;}}
class Scholar extends Student implements BusUser {Scholar(String n){super(n);}double calculateFee(){return 20000.0;}public double getTransportFee(){return 12000.0;}}
public class CollegeFeeCounter {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=sc.nextInt();double total=0;for(int i=0;i<n;i++){String type=sc.next(),name=sc.next();Student s;switch(type){case "DAY_SCHOLAR":s=new DayScholar(name);break;case "HOSTELLER":s=new Hosteller(name);break;default:s=new Scholar(name);}double fee=s.getTotalFee();System.out.printf("%s: %.2f%n",s.name,fee);total+=fee;}System.out.printf("Total Collected: %.2f%n",total);sc.close();}}